const cloneOptions = (opts) => (opts ? opts.map((o) => ({ ...o })) : [])

const resolveOptionLabel = (options, value) => {
  if (!hasVal(value) || !options?.length) return value || ''
  const match = options.find((o) => o.value === value)
  return match ? match.label : value
}

const hasVal = (v) => v != null && String(v).trim() !== ''

export function getMakeOptions(productType) {
  const bucket = MMV_BY_PRODUCT_TYPE[productType]
  return bucket ? cloneOptions(bucket.makes) : []
}

export function getModelOptions(productType, make) {
  if (!productType || !make) return []
  const bucket = MMV_BY_PRODUCT_TYPE[productType]
  return bucket ? cloneOptions(bucket.modelsByMake[make]) : []
}

export function getVariantOptions(productType, make, model) {
  if (!productType || !make || !model) return []
  const bucket = MMV_BY_PRODUCT_TYPE[productType]
  return bucket ? cloneOptions(bucket.variantsByMakeModel[make + '::' + model]) : []
}

export function getMakeLabel(productType, make) {
  return resolveOptionLabel(getMakeOptions(productType), make)
}

export function getModelLabel(productType, make, model) {
  return resolveOptionLabel(getModelOptions(productType, make), model)
}

export function getVariantLabel(productType, make, model, variant) {
  return resolveOptionLabel(getVariantOptions(productType, make, model), variant)
}